# ---- 写盘与断言 ----
assert set(P.keys()) == set(IDS), "id 集与 B17 清单不一致: %s" % (set(IDS) ^ set(P.keys()))
assert len(P) == 20, "例数断言失败: %d" % len(P)
total = 0
for cid in IDS:
    rec = {"case_id": cid,
           "prediction_text": P[cid]["prediction_text"],
           "basis": P[cid]["basis"],
           "confidence": P[cid]["confidence"],
           "trigger": P[cid]["trigger"]}
    path = os.path.join(OUT, cid + ".json")
    with open(path, "w", encoding="utf-8") as f:
        json.dump(rec, f, ensure_ascii=False, indent=1)
    total += os.path.getsize(path)
# 逐件精确打开自验
for cid in IDS:
    path = os.path.join(OUT, cid + ".json")
    with open(path, encoding="utf-8") as f:
        d = json.load(f)
    assert d["case_id"] == cid and set(d.keys()) == {"case_id","prediction_text","basis","confidence","trigger"}
    assert set(d["trigger"].keys()) == {"changed_main","reserve_used","disputed","reason"}
ly = [c for c in IDS if c.startswith("LY-")]
cm = sum(1 for c in ly if P[c]["trigger"]["changed_main"])
ru = sum(1 for c in ly if P[c]["trigger"]["reserve_used"])
di = sum(1 for c in ly if P[c]["trigger"]["disputed"])
print("written:", len(IDS), "total_bytes:", total)
print("liuyao trigger counts: changed_main=%d reserve_used=%d disputed=%d" % (cm, ru, di))
